mapper.select:
SELECT
    DISTINCT
    t.*
FROM
    scc_sou_jc_agreement t
    LEFT JOIN scc_sou_jc_agreement_info ssjai ON t.AGREEMENT_ID  = ssjai.AGREEMENT_ID
    LEFT JOIN scc_sou_jc_agreement_org ssjao ON t.AGREEMENT_ID = ssjao.AGREEMENT_ID
WHERE
    t.AGREEMENT_TYPE = #{ja.agreementType,jdbcType=VARCHAR}

        AND t.AGREEMENT_CODE LIKE CONCAT('%', #{ja.agreementCode,jdbcType=VARCHAR}, '%')


        AND t.SUP_NAME LIKE CONCAT('%', #{ja.supName,jdbcType=VARCHAR}, '%')


        AND t.BUY_PERSON_ID = #{ja.buyPersonId,jdbcType=BIGINT}


        AND t.AGREEMENT_NAME LIKE CONCAT('%', #{ja.agreementName,jdbcType=VARCHAR}, '%')


        AND t.COMPANY_ID = #{ja.companyId,jdbcType=BIGINT}


        AND t.CREATED_FULL_NAME LIKE CONCAT('%', #{ja.createdFullName,jdbcType=VARCHAR}, '%')


        AND t.AGREEMENT_STATUS = #{ja.agreementStatus,jdbcType=VARCHAR}


        AND t.EFFECTIVE_START_DATE >= #{ja.effectiveStartDate,jdbcType=TIMESTAMP}


        AND t.EFFECTIVE_END_DATE <= #{ja.effectiveEndDate,jdbcType=TIMESTAMP}


        AND t.CREATION_DATE >= #{ja.operatorStartDate,jdbcType=TIMESTAMP}


        AND t.CREATION_DATE <= #{ja.operatorEndDate,jdbcType=TIMESTAMP}


        AND t.SUPPLY_AREA LIKE CONCAT('%', #{ja.supplyArea,jdbcType=VARCHAR}, '%')



    AND ssjao.BUY_ORG_ID = #{ja.buyOrgId,jdbcType=BIGINT}


    AND ssjai.MATERIAL_CODE = #{ja.materialCode,jdbcType=VARCHAR}

    ORDER BY LAST_UPDATE_DATE DESC

SELECT ao.BUY_ORG_CODE AS buyOrgCode, ag.SUPPLY_AREA AS supplyArea, COUNT(*) AS num FROM scc_sou_jc_agreement_org ao LEFT JOIN scc_sou_jc_agreement ag ON ao.AGREEMENT_ID = ag.AGREEMENT_ID WHERE ag.AGREEMENT_ID IN
#{item}
AND ag.AGREEMENT_STATUS IN ('DRAFT', 'APPROVING', 'APPROVED') GROUP BY ao.BUY_ORG_CODE, ag.SUPPLY_AREA HAVING COUNT(*) > 1

SELECT ai.*, ao.BUY_ORG_ID companyId, a.SUPPLY_AREA, a.SUP_ID, a.SUP_CODE, a.SUP_NAME, a.CURRENCY_TYPE, a.INVOICE_TYPE, a.PAYMENT, a.PAY_WAY, a.AGREEMENT_TYPE FROM scc_sou_jc_agreement_info ai JOIN scc_sou_jc_agreement a ON ai.AGREEMENT_ID = a.AGREEMENT_ID JOIN scc_sou_jc_agreement_org ao ON ao.AGREEMENT_ID = a.AGREEMENT_ID WHERE a.AGREEMENT_STATUS = 'EXECUTING' and a.EFFECTIVE_START_DATE <= NOW() and a.EFFECTIVE_END_DATE >= NOW() and ai.MATERIAL_ID IN
#{materialId}
and ao.BUY_ORG_ID IN
#{orgId}

SELECT ai.MATERIAL_CODE, ssja.AGREEMENT_ID, ssja.SUPPLY_AREA FROM scc_sou_jc_agreement_info ai LEFT JOIN scc_sou_jc_agreement ssja ON ai.AGREEMENT_ID = ssja.AGREEMENT_ID WHERE ssja.AGREEMENT_STATUS IN ('DRAFT', 'EXECUTE', 'EXECUTING')
AND ssja.AGREEMENT_CODE != #{agreementCode,jdbcType=VARCHAR}
AND ai.MATERIAL_CODE = #{newMaterialCode,jdbcType=VARCHAR}
AND ssja.EFFECTIVE_START_DATE <= #{effectiveEndDate} and ssja.EFFECTIVE_END_DATE >= #{effectiveStartDate}
group by ai.MATERIAL_CODE, ssja.AGREEMENT_ID, ssja.SUPPLY_AREA

SELECT ssja.COMPANY_ID, ssja.COMPANY_CODE, ssja.COMPANY_NAME, ssja.SUP_NAME, ssja.SUPPLY_AREA, ssjai.MATERIAL_ID, ssjai.MATERIAL_CODE, ssjai.MATERIAL_NAME, ssjai.STANDARDS, ssjai.UNIT, ssja.EFFECTIVE_START_DATE, ssja.EFFECTIVE_END_DATE, ssja.BUY_PERSON_ID, ssja.BUY_PERSON_CODE, ssja.BUY_PERSON_NAME, ssja.AGREEMENT_STATUS, ssja.AGREEMENT_TYPE FROM scc_sou_jc_agreement_info ssjai LEFT JOIN scc_sou_jc_agreement ssja ON ssjai.AGREEMENT_ID = ssja.AGREEMENT_ID
AND ssja.COMPANY_CODE = #{ja.companyCode,jdbcType=VARCHAR}
AND ssjai.MATERIAL_CODE = #{ja.materialCode,jdbcType=VARCHAR}
AND ssjai.MATERIAL_NAME LIKE CONCAT('%', #{ja.materialName,jdbcType=VARCHAR}, '%')
AND ssjai.STANDARDS LIKE CONCAT('%', #{ja.standards,jdbcType=VARCHAR}, '%')
AND ssja.SUP_CODE LIKE CONCAT('%', #{ja.supCode,jdbcType=VARCHAR}, '%')
AND ssja.SUP_NAME LIKE CONCAT('%', #{ja.supName,jdbcType=VARCHAR}, '%')
AND ssja.SUPPLY_AREA LIKE CONCAT('%', #{ja.supplyArea,jdbcType=VARCHAR}, '%')
AND ssja.AGREEMENT_STATUS = #{ja.agreementStatus,jdbcType=VARCHAR}
AND ssja.BUY_PERSON_NAME = #{ja.buyPersonCode,jdbcType=VARCHAR}
AND ssja.AGREEMENT_TYPE = #{ja.agreementType,jdbcType=VARCHAR}
ORDER BY ssja.LAST_UPDATE_DATE DESC

SELECT ssja.AGREEMENT_CODE AS agreementCode, ssja.AGREEMENT_NAME AS agreementName, ssja.CHANGE_VERSION AS changeVersion, ssja.COMPANY_NAME AS companyName, ssja.SUP_NAME AS supName, ssja.EFFECTIVE_START_DATE AS effectiveStartDate, ssja.EFFECTIVE_END_DATE AS effectiveEndDate, ssja.CREATION_DATE AS creationDate, ( SELECT group_concat(aorg.BUY_ORG_NAME) FROM scc_sou_jc_agreement_org aorg WHERE aorg.AGREEMENT_ID = ssja.AGREEMENT_ID) AS orgName, ssja.BUY_PERSON_NAME AS buyPersonName, ssja.CREATED_FULL_NAME AS createdFullName, ssja.AGREEMENT_STATUS AS agreementStatus, ssja.INVOICE_TYPE AS invoiceType, ssja.SUPPLY_AREA, ssjai.MATERIAL_LINE AS materialLine, ssjai.MATERIAL_CODE AS materialCode, ssjai.MATERIAL_NAME AS materialName, ssjai.GOODS_TYPE_NAME AS goodsTypeName, ssjai.STANDARDS AS standards, ssjai.UNIT AS unit, ssjai.BRAND AS brand, ssjai.TAX_RATE AS taxRate, ssjai.IS_TIERED_PRICING AS isTieredPricing, ssjai.PRICE_TAX AS priceTax, ssjai.RATE_PRICE AS ratePrice, ssjai.REFERENCE_PRICE AS referencePrice, ssjai.LEAD_TIME AS leadTime, ssjai.SELL_BY_DATE AS sellByDate, ssjai.START_NUM AS startNum, ssjai.MULTIPLE_START_NUM AS multipleStartNum, ssjai.AGREEMENT_DES AS agreementDes FROM scc_sou_jc_agreement_info ssjai LEFT JOIN scc_sou_jc_agreement ssja ON ssjai.AGREEMENT_ID = ssja.AGREEMENT_ID
AND ssja.AGREEMENT_TYPE = #{ja.agreementType,jdbcType=VARCHAR}
AND ssja.AGREEMENT_CODE like CONCAT('%', #{ja.agreementCode,jdbcType=VARCHAR}, '%')
AND ssja.SUP_NAME like CONCAT('%', #{ja.supName,jdbcType=VARCHAR}, '%')
AND ssja.BUY_PERSON_Id = #{ja.buyPersonId,jdbcType=BIGINT}
AND ssja.AGREEMENT_NAME like CONCAT('%', #{ja.agreementName,jdbcType=VARCHAR}, '%')
AND ssja.COMPANY_ID = #{ja.companyId,jdbcType=BIGINT}
AND ssja.CREATED_FULL_NAME like CONCAT('%', #{ja.createdFullName,jdbcType=VARCHAR}, '%')
AND ssja.EFFECTIVE_START_DATE >= #{ja.effectiveStartDate,jdbcType=TIMESTAMP}
AND ssja.EFFECTIVE_END_DATE <= #{ja.effectiveEndDate,jdbcType=TIMESTAMP}
AND ssja.AGREEMENT_STATUS = #{ja.agreementStatus,jdbcType=VARCHAR}
AND ssja.CREATION_DATE >= #{ja.effectiveStartDate,jdbcType=TIMESTAMP}
AND ssja.CREATION_DATE <= #{ja.effectiveEndDate,jdbcType=TIMESTAMP}
AND ssja.AGREEMENT_ID IN
#{item}
ORDER BY ssja.LAST_UPDATE_DATE DESC
